export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type Rejection = {
  provider: Provider;
  reason: RefusalReason;
};

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: Classification;
  rejections: Rejection[];
};

export interface ServiceResponse {
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found" | "service_unavailable";
      };
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | { kind: "confirmed"; provider: Provider; bookingId: string }
  | { kind: "refused"; rejection: Rejection }
  | { kind: "throttled"; provider: Provider; retryAtMs: number }
  | {
      kind: "aborted";
      failedAt: Provider;
      classification: Exclude<Classification, "repository_failure">;
    };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isValidRejection(value: unknown): value is Rejection {
  return isObject(value) && isProvider(value.provider) && isRefusalReason(value.reason);
}

function parseRejections(value: unknown): Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections = value.filter(isValidRejection).map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
  return rejections.length === value.length ? rejections : undefined;
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    value.id.length === 0 ||
    typeof value.routeCode !== "string" ||
    value.routeCode.length === 0 ||
    typeof value.parcelGrams !== "number" ||
    !Number.isSafeInteger(value.parcelGrams) ||
    value.parcelGrams <= 0
  ) {
    return undefined;
  }

  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...fields,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return { ...fields, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicRejections(rejections: readonly Rejection[]): Rejection[] {
  return rejections.map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: publicRejections(shipment.rejections),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: publicRejections(shipment.rejections),
      };
  }
}

function requestFor(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function validRetryAt(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

function classifyAtlasRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error)) {
    return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
  }
  if (error.code === "cannot_ship") {
    return isRefusalReason(error.reason)
      ? { kind: "refused", rejection: { provider: "atlas", reason: error.reason } }
      : { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
  }
  if (error.code === "rate_limited") {
    return validRetryAt(error.retryAtMs, nowMs)
      ? { kind: "throttled", provider: "atlas", retryAtMs: error.retryAtMs }
      : { kind: "aborted", failedAt: "atlas", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: "atlas", classification: "unknown_failure" };
}

function classifyBeaconRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error)) {
    return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
  }
  if (error.type === "rejected") {
    const details = error.details;
    return isObject(details) && isRefusalReason(details.reason)
      ? { kind: "refused", rejection: { provider: "beacon", reason: details.reason } }
      : { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
  }
  if (error.type === "throttled") {
    const details = error.details;
    return isObject(details) && validRetryAt(details.retryAtMs, nowMs)
      ? { kind: "throttled", provider: "beacon", retryAtMs: details.retryAtMs }
      : { kind: "aborted", failedAt: "beacon", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", failedAt: "beacon", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, response: unknown): CarrierOutcome {
  if (provider === "atlas") {
    return isObject(response) &&
      typeof response.bookingId === "string" &&
      response.bookingId.length > 0
      ? { kind: "confirmed", provider, bookingId: response.bookingId }
      : { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
  }
  return isObject(response) && typeof response.reference === "string" && response.reference.length > 0
    ? { kind: "confirmed", provider, bookingId: response.reference }
    : { kind: "aborted", failedAt: provider, classification: "invalid_provider_response" };
}

function responseForAbort(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections: publicRejections(rejections),
    },
  };
}

function logAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
) {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: publicRejections(rejections),
  });
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  establishedRejections: readonly Rejection[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(shipment.id, shipment);
  } catch {
    logAbort(dependencies, shipment.id, "repository", "repository_failure", establishedRejections);
    return responseForAbort(shipment.id, "repository", "repository_failure", establishedRejections);
  }
  return undefined;
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<CarrierOutcome> {
  try {
    const response =
      provider === "atlas"
        ? await dependencies.atlas.book(requestFor(shipment, command.recipient))
        : await dependencies.beacon.reserve(requestFor(shipment, command.recipient));
    return classifyConfirmation(provider, response);
  } catch (error) {
    return provider === "atlas"
      ? classifyAtlasRejection(error, command.nowMs)
      : classifyBeaconRejection(error, command.nowMs);
  }
}

function hasRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      logAbort(dependencies, command.shipmentId, "repository", "repository_failure", []);
      return responseForAbort(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (shipment === undefined) {
      logAbort(dependencies, command.shipmentId, "repository", "repository_failure", []);
      return responseForAbort(command.shipmentId, "repository", "repository_failure", []);
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }

    let nextProvider: Provider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
    let rejections = shipment.state === "deferred" ? publicRejections(shipment.rejections) : [];

    while (!hasRefusal(rejections, nextProvider)) {
      const outcome = await attemptCarrier(dependencies, nextProvider, shipment, command);
      switch (outcome.kind) {
        case "confirmed": {
          const dispatched: DispatchedShipment = {
            schemaVersion: 1,
            id: shipment.id,
            routeCode: shipment.routeCode,
            parcelGrams: shipment.parcelGrams,
            state: "dispatched",
            provider: outcome.provider,
            bookingId: outcome.bookingId,
            dispatchedAtMs: command.nowMs,
          };
          const saveFailure = await saveDecision(dependencies, dispatched, rejections);
          if (saveFailure) {
            return saveFailure;
          }
          dependencies.logger.info({
            shipmentId: shipment.id,
            action: "dispatched",
            provider: outcome.provider,
          });
          return { status: 200, body: publicShipment(dispatched) };
        }
        case "refused":
          rejections = [...rejections, outcome.rejection];
          if (outcome.rejection.provider === "atlas") {
            nextProvider = "beacon";
            break;
          }
          if (outcome.rejection.provider === "beacon") {
            const unavailable: UnavailableShipment = {
              schemaVersion: 1,
              id: shipment.id,
              routeCode: shipment.routeCode,
              parcelGrams: shipment.parcelGrams,
              state: "unavailable",
              rejections,
            };
            const saveFailure = await saveDecision(dependencies, unavailable, rejections);
            if (saveFailure) {
              return saveFailure;
            }
            dependencies.logger.info({
              shipmentId: shipment.id,
              action: "unavailable",
              rejections: publicRejections(rejections),
            });
            return { status: 422, body: publicShipment(unavailable) };
          }
          break;
        case "throttled": {
          const deferred: DeferredShipment = {
            schemaVersion: 1,
            id: shipment.id,
            routeCode: shipment.routeCode,
            parcelGrams: shipment.parcelGrams,
            state: "deferred",
            nextProvider: outcome.provider,
            retryAtMs: outcome.retryAtMs,
            rejections,
          };
          const saveFailure = await saveDecision(dependencies, deferred, rejections);
          if (saveFailure) {
            return saveFailure;
          }
          dependencies.logger.info({
            shipmentId: shipment.id,
            action: "deferred",
            provider: outcome.provider,
            retryAtMs: outcome.retryAtMs,
            rejections: publicRejections(rejections),
          });
          return { status: 202, body: publicShipment(deferred) };
        }
        case "aborted":
          logAbort(dependencies, shipment.id, outcome.failedAt, outcome.classification, rejections);
          return responseForAbort(shipment.id, outcome.failedAt, outcome.classification, rejections);
      }
    }

    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections,
    };
    const saveFailure = await saveDecision(dependencies, unavailable, rejections);
    if (saveFailure) {
      return saveFailure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "unavailable",
      rejections: publicRejections(rejections),
    });
    return { status: 422, body: publicShipment(unavailable) };
  }

  return { handle };
}
